'use strict';

var SplitSymbol = require( './../lib' );

function splitter() {
	var obj;

	obj = {};

	if ( SplitSymbol ) {
		// Define custom split behavior:
		obj[ SplitSymbol ] = split;
	}
	return obj;

	function split( str ) {
		// Split the input string by commas and trim whitespace:
		return str.split( ',' ).map( function( part ) {
			return part.trim();
		});
	}
}

var obj = splitter();
var str = 'apple, banana, cherry';
var result = str.split( obj );

console.log( result );
// => [ 'apple', 'banana', 'cherry' ]
